"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[4351],{4351:(e,t,a)=>{a.d(t,{IV:()=>o,oh:()=>n});let n=[{slug:"brokerage-launch-checklist",title:"The brokerage launch checklist",category:"Launch",audience:"Founders and operations leads",readMinutes:8,summary:"The decisions to make before go-live — entities, accounts, onboarding, payments and partners — in the order that avoids rework.",keyPoints:["Decide the operating model before choosing tools","Onboarding, payments and partners share one client record","Test the unhappy paths, not just the demo path","Launch with the audit trail already switched on"],sections:[{heading:"Start with the operating model, not the software",body:["Before comparing platforms, write down how the business will actually run: who owns a lead, who approves a withdrawal, who answers a partner asking where their commission is. Most launch delays are not technical; they are decisions nobody made, discovered the week before go-live.","Keep the list short. Five decisions cover most of it: the client journey from first click to first deposit, the account types you will offer, the payment methods by region, the partner model, and who holds approval rights for money movement. Everything else can evolve after launch."]},{heading:"One client record, shared by every workflow",body:["Onboarding, payments, support and partner attribution all describe the same person. If each workflow keeps its own copy of that person, launch week produces four versions of the truth and a reconciliation backlog on day one.","Agree the shared record early: one identifier, one verification state, one account list. Then let each workflow read from it and write its own events back to it. The launch checklist item is not a feature — it is the agreement that there is one record."]},{heading:"Test the unhappy paths",body:["Demos show the happy path: a clean application, an instant approval, a deposit that lands. Real launches meet the rejected document, the failed deposit, the partner whose link was shared twice, the withdrawal that needs a second approver who is on leave.","Walk each unhappy path once before launch, with the people who will handle it live. Note where the handoff is unclear and fix the process, not just the screen. The firms that do this launch quietly; the firms that skip it launch loudly, on support tickets."]}]},{slug:"ib-programme-design",title:"Designing an IB programme people trust",category:"Partners",audience:"Partner managers and commercial leads",readMinutes:7,summary:"Tiers, attribution rules and a commission ledger your partners can check themselves — trust is a feature, not a promise.",keyPoints:["Write the attribution rule down before the first referral","Every earning needs a cause a partner can inspect","Adjustments are visible rows, never silent edits","Pay on a schedule partners can set their watch by"],sections:[{heading:"Attribution first, rates second",body:["Partners argue about attribution far more than about rates. First-touch or last-touch, referral link or code, a window of days or a lifetime claim — the choice matters less than the fact that it is written down, applied consistently, and visible to the partner it affects.","Decide the rule for the messy cases too: a client who clicks two links, a referral that arrives after the account exists, a sub-IB who refers another sub-IB. If the rulebook is silent, the dispute is settled by whoever shouts loudest, and that is never the partner."]},{heading:"A ledger, not a monthly number",body:["A commission statement should be a summary of rows the partner could have seen all month: this client, this volume, this rule, this amount. When the rows are visible, the monthly total is a formality. When they are not, the total is a claim the partner has no way to check.","Keep adjustments in the ledger as their own rows with a reason and an approver. Corrections happen — volume is restated, a trade is adjusted — and partners accept them when they can see them. What they do not accept is a number that quietly changed."]},{heading:"Payouts are a promise with a date",body:["Pick a payout rhythm and keep it. Partners plan around it, and a missed date costs more trust than a smaller rate ever would. Publish the schedule, the minimum payout and the approval steps, and make the partner's payout status visible to the partner.","Build in the review step honestly: payouts go through approval because money movement deserves a second pair of eyes. The programme that pays late because of a broken process loses partners; the programme that pays on time because of a boring, reliable one keeps them."]}]},{slug:"onboarding-kyc-operations",title:"Onboarding and KYC operations, end to end",category:"Operations",audience:"Operations and compliance teams",readMinutes:9,summary:"Journey design, verification, approval queues and the handoff to a live trading account — run as one workflow, not five.",keyPoints:["Ask for information when it earns its place","Different applicants need different journeys","Reviewers need context, not bare tickets","Measure drop-off by step, not by gut feel"],sections:[{heading:"Design the journey around the applicant",body:["An application is a conversation, and the applicant decides how long it lasts. The first step should be small and rewarding — an account that exists, a dashboard that already feels like theirs. Verification arrives when the applicant can see what it unlocks, not before.","Individuals, corporate applicants and professional clients are not the same journey with different labels. Corporate onboarding needs beneficial ownership and authorised signatories; individuals need speed. Forcing one path to serve all three serves none of them."]},{heading:"Verification is a service, not a gate",body:["Document upload, identity checks and screening feel very different depending on when they happen and how failures are handled. A rejected document with a clear reason and a one-tap retry is a minor interruption; the same rejection with a generic error is a lost applicant.","Keep the verification state on the shared client record, so support, sales and compliance all see the same status. The applicant should never have to explain to one team what another team already decided."]},{heading:"Approval queues are where journeys go to wait",body:["Most onboarding delay lives in queues, not in forms. Give reviewers the full context with each case — documents, flags, history, the applicant's own words — and give the queue itself a visible age, so the oldest case is the next case, not the one someone remembers.","Measure four things: drop-off by step, time to first deposit, queue age, and the share of applications needing a second touch. Those numbers point at the exact step to fix next, which is more useful than any general complaint that onboarding is slow."]}]},{slug:"payment-routing",title:"Payment routing without the guesswork",category:"Payments",audience:"Finance and operations leads",readMinutes:6,summary:"Routing rules, cascading retry and reconciliation: how deposits stop being a daily mystery for your finance team.",keyPoints:["Route by country, currency, amount and client profile","A declined payment deserves a second route, not a dead end","Every payment needs a status trace the client can follow","Reconciliation is a check, not a monthly investigation"],sections:[{heading:"Rules before routes",body:["Provider-agnostic routing starts with rules, not with providers. Which methods are available in which country, for which currencies, above and below which amounts, for which client profiles? Write the rules down and the routing follows; skip them and every deposit becomes a judgement call.","Priority and weighted routing are the same idea at different scales: send traffic where it succeeds, shift it when conditions change, and keep the decision visible so finance can explain why a payment took the route it took."]},{heading:"Declines are part of the flow",body:["A declined card is not the end of a deposit; it is the middle of one. Cascading retry — trying the next suitable route after a decline — recovers deposits that would otherwise become support tickets, as long as the retry rules are explicit and the client always knows what is happening.","The line that matters: retry logic must be boring and predictable. A client who sees two attempts and one clear outcome trusts the system. A client who sees a charge they cannot explain does not, and no retry rate is worth that."]},{heading:"Reconciliation closes the loop",body:["Deposits, withdrawals and approvals should reconcile three ways: the payment provider's record, the CRM record and the trading platform's record. When all three point at one shared identifier, reconciliation is a check that runs itself. When they do not, it is a monthly investigation.","Keep an exception queue for the payments that do not reconcile, and work it daily. Five visible exceptions are a morning's work; fifty hidden ones are a quarter-end crisis."]}]},{slug:"reporting-starter-guide",title:"Reading your own operations: a reporting starter guide",category:"Analytics",audience:"Operators, team leads and founders",readMinutes:6,summary:"Funnels, exception queues and audit trails — the small set of views that tells an operator what actually needs attention.",keyPoints:["Start with four views, not forty dashboards","Exceptions deserve a queue, not a report","Funnels show where effort leaks away","Audit trails turn arguments into lookups"],sections:[{heading:"Four views cover most days",body:["An operator's morning needs four things: the sales funnel (where leads stall), the onboarding funnel (where applicants stall), the payments view (what moved, what failed, what is waiting), and the exception queue (what needs a human today). Everything else is a deeper cut of one of those four.","Resist the forty-dashboard trap. A dashboard nobody opens is worse than no dashboard, because it creates the impression that someone is watching a number nobody is watching."]},{heading:"Exceptions are work, not statistics",body:["A failed deposit, a stuck application, a partner payout awaiting approval — these are tasks with owners and ages, not rows in a monthly report. Give each exception queue a visible oldest item and a named owner, and the queue shrinks. Bury exceptions in a report and they grow quietly.","Review the queues together once a week. The same exception appearing in two queues is usually one root cause wearing two hats, and fixing it once beats working around it twice."]},{heading:"Audit trails are for Tuesdays, not just auditors",body:["The audit trail's real audience is not the regulator; it is the team member on a Tuesday trying to answer 'who changed this and why?' A complete trail — who, what, when, and the reason given — turns that question from an investigation into a lookup.","Record the reason, not just the change. A leverage change with a note is a decision; the same change without one is a mystery that will cost someone an afternoon."]}]}],o=[{id:"onboarding-webinar",title:"From first lead to funded account",format:"Live webinar \xb7 45 min + Q&A",audience:"Operations and growth teams",description:"Onboarding that converts: fewer fields, clearer steps, verification that arrives when it earns its place — and a human at the end of the journey.",points:["Where applicants actually drop off, and what to change first","Designing different journeys for individuals and corporates","Approval queues that move at the speed of the business"]},{id:"partner-economics-webinar",title:"Partner economics: rebates, attribution and trust",format:"Live webinar \xb7 45 min + Q&A",audience:"Partner managers and commercial leads",description:"How rebate programmes stay trustworthy as they grow: attribution rules, a ledger partners can inspect, and payouts on a schedule.",points:["Attribution rules for the messy cases, written down","The commission ledger as a shared record, not a monthly claim","Payout rhythms partners can plan around"]},{id:"payments-webinar",title:"Payments for brokers: routing, retry and reconciliation",format:"Live webinar \xb7 45 min + Q&A",audience:"Finance and operations leads",description:"Routing rules, cascading retry and three-way reconciliation — how the money side of a brokerage stops being a daily firefight.",points:["Routing by country, currency, amount and client profile","Declines as part of the flow, not the end of it","Exception queues worked daily instead of quarterly"]},{id:"tradeops-webinar",title:"TradeOps without the 2 a.m. spreadsheet",format:"Live webinar \xb7 45 min + Q&A",audience:"Dealing and operations teams",description:"Server operations with dry-runs, approvals and audit trails: batch changes your future self will not have to apologise for.",points:["Dry-run before you change a live server","Four-eyes review for the changes that matter","Audit logs that answer questions instead of raising them"]}]}}]);